"""Independent slow reference using Fractions and search-based encoding."""
from fractions import Fraction as Fr


class Ref:
    def __init__(self, ebits, fbits, mode):
        self.ebits, self.fbits, self.mode = ebits, fbits, mode
        self.Eall = 2 ** ebits - 1
        self.bias = 2 ** (ebits - 1) - 1
        self.F = 2 ** fbits
        self.emin = 1 - self.bias
        self.emax = self.Eall - 1 - self.bias
        self.width = 1 + ebits + fbits

    def decode(self, hx):
        v = int(hx, 16)
        b = bin(v)[2:].zfill(self.width)[-self.width:]
        s = int(b[0]); e = int(b[1:1 + self.ebits], 2); f = int(b[1 + self.ebits:], 2)
        return s, e, f

    def kind(self, hx):
        s, e, f = self.decode(hx)
        if e == self.Eall:
            if f == 0:
                return ('inf', s)
            return ('nan', s, bool(f >> (self.fbits - 1)))
        if e == 0 and f == 0:
            return ('zero', s)
        if e == 0:
            return ('fin', s, Fr(f) * Fr(2) ** (1 - self.bias - self.fbits))
        return ('fin', s, Fr(self.F + f) * Fr(2) ** (e - self.bias - self.fbits))

    def run(self, pairs):
        nan = False; invalid = False; pinf = False; ninf = False
        prods = []   # (sign, Fraction|None-zero)
