import sys, random, json
sys.path.insert(0,'/app'); sys.path.insert(0,'/app/dev')
from main import solve
from slowref import Ref
random.seed(int(sys.argv[1])); N=int(sys.argv[2])
MODES=['RNE','RNA','RTZ','RUP','RDN']
combos=[]
for ebits in range(3,12):
    for fbits in range(2,53):
        if 1+ebits+fbits<=64: combos.append((ebits,fbits))
fails=0
for it in range(N):
    ebits,fbits=random.choice(combos)
    W=1+ebits+fbits; E=2**ebits-1; F=2**fbits
    def pat():
        r=random.random()
        if r<0.4: return format(random.randrange(1<<W),'x')
        e=random.choice([0,0,1,1,2,E-1,E-2,E]); f=random.choice([0,0,1,F-1,F//2,1<<(fbits-1),random.randrange(F)])
        return format(((random.randint(0,1)<<ebits)|e)<<fbits|f,'x')
    pairs=[[pat(),pat()] for _ in range(random.choice([1,2,3,7,64]))]
    mode=random.choice(MODES)
    req={'ebits':ebits,'fbits':fbits,'mode':mode,'pairs':pairs}
    got=solve(req); exp=Ref(ebits,fbits,mode).run(pairs)
    if int(got['bits'],16)!=int(exp['bits'],16) or sorted(got['flags'])!=sorted(exp['flags']):
        fails+=1; print('MISMATCH',json.dumps(req)); print(' got',got,'exp',exp)
        if fails>5: sys.exit(1)
print('fuzzwide done N',N,'fails',fails)
